import json, sys, re

data = json.load(sys.stdin)
exps = data['data']['experiments']

eval_exps = {k: v for k, v in exps.items() if 'eval' in k.lower()}

# Parse experiment IDs to extract scale, dose, seed, eval_type, version
def parse_exp_id(exp_id):
    info = {}
    # Scale
    if '05B' in exp_id: info['scale'] = '0.5B'
    elif '15B' in exp_id: info['scale'] = '1.5B'
    elif '3B' in exp_id: info['scale'] = '3B'
    else: info['scale'] = 'unknown'

    # Dose
    m = re.search(r'd(\d{3})', exp_id)
    if m:
        dose_map = {'000': '0%', '005': '5%', '025': '25%', '100': '100%'}
        info['dose'] = dose_map.get(m.group(1), m.group(1))
    else:
        info['dose'] = 'N/A'

    # Seed
    m = re.search(r's(\d+)', exp_id)
    if m: info['seed'] = int(m.group(1))
    else: info['seed'] = None

    # Eval type
    if 'para_aligned' in exp_id:
        info['eval_type'] = 'para_aligned'
    elif 'aligned' in exp_id:
        info['eval_type'] = 'aligned'
    elif 'raw' in exp_id or 'raw_gen' in exp_id:
        info['eval_type'] = 'raw'
    elif 'batch' in exp_id:
        info['eval_type'] = 'batch'
    else:
        info['eval_type'] = 'standard'

    # Version
    m = re.search(r'_v(\d+)', exp_id)
    info['version'] = int(m.group(1)) if m else 1

    # Experiment series
    m = re.search(r'(exp_\d+)', exp_id)
    info['series'] = m.group(1) if m else 'unknown'

    return info

# Normalize metrics to simple float values
def normalize_metrics(metrics):
    if metrics is None:
        return None
    result = {}
    for k, v in metrics.items():
        if isinstance(v, (int, float)):
            result[k] = round(float(v), 4)
        elif isinstance(v, dict):
            # nested metrics (some have accuracy/correct/total or dose breakdowns)
            result[k] = v
        elif isinstance(v, str):
            result[k] = v
    return result

# Output structured summary
results = []
for exp_id, exp_data in sorted(eval_exps.items()):
    parsed = parse_exp_id(exp_id)
    metrics = normalize_metrics(exp_data.get('metrics'))

    # Also check spec-level info
    seed = parsed['seed']
    model_name = None
    checkpoint_source = None
    for path in [exp_data.get('reproduce', {}).get('spec', {}), exp_data.get('spec', {})]:
        if isinstance(path, dict):
            if not seed and path.get('seed'): seed = path['seed']
            if not model_name and path.get('model_name'): model_name = path['model_name']
            if not checkpoint_source and path.get('checkpoint_source'): checkpoint_source = path['checkpoint_source']

    results.append({
        'exp_id': exp_id,
        'series': parsed['series'],
        'scale': parsed['scale'],
        'dose': parsed['dose'],
        'seed': seed,
        'eval_type': parsed['eval_type'],
        'version': parsed['version'],
        'status': exp_data['status'],
        'has_metrics': metrics is not None and len(metrics) > 0,
        'metrics': metrics,
        'model_name': model_name,
        'checkpoint_source': checkpoint_source,
    })

# Print organized by scale
for scale in ['0.5B', '1.5B', '3B', 'unknown']:
    scale_exps = [r for r in results if r['scale'] == scale]
    if not scale_exps:
        continue
    print(f'\\n{\"=\"*80}')
    print(f'SCALE: {scale} ({len(scale_exps)} experiments)')
    print(f'{\"=\"*80}')

    for dose in ['0%', '5%', '25%', '100%', 'N/A']:
        dose_exps = [r for r in scale_exps if r['dose'] == dose]
        if not dose_exps:
            continue
        print(f'\\n  --- Dose: {dose} ---')
        for exp in sorted(dose_exps, key=lambda x: (x['eval_type'], x['seed'] or 0, x['version'])):
            seed_str = f's{exp[\"seed\"]}' if exp['seed'] else 'no_seed'
            print(f'  [{exp[\"exp_id\"]}]  type={exp[\"eval_type\"]}  {seed_str}  v{exp[\"version\"]}  metrics={\"YES\" if exp[\"has_metrics\"] else \"NO\"}')
            if exp['metrics']:
                for mk, mv in exp['metrics'].items():
                    if isinstance(mv, dict):
                        print(f'    {mk}: {json.dumps(mv)}')
                    else:
                        print(f'    {mk}: {mv}')
